/* ---------- tokens (palette: dataviz reference instance, light + dark) ---------- */
.dash,
.viz-tooltip {
  color-scheme: light;
  --surface-1: #fcfcfb;
  --page: #f9f9f7;
  --text-primary: #0b0b0b;
  --text-secondary: #52514e;
  --text-muted: #898781;
  --grid: #e1e0d9;
  --axis: #c3c2b7;
  --border: rgba(11, 11, 11, 0.1);
  --series-1: #2a78d6;
  --series-2: #eb6834;
  --series-3: #1baf7a;
  --series-4: #eda100;
  --series-5: #e87ba4;
  --good-text: #006300;
  --bad-text: #d03b3b;
  --status-good: #0ca30c;
  --status-warning: #fab219;
  --status-critical: #d03b3b;
  --meter-fill: #2a78d6;
  --meter-track: #cde2fb;
  --accent: #2a78d6;
  --veil: rgba(252, 252, 251, 0.55);
  --focus: #2a78d6;
  --shadow: 0 12px 32px rgba(11, 11, 11, 0.18);
  --guide: rgba(11, 11, 11, 0.045);
}

.g-root_theme_dark .dash,
.g-root_theme_dark .viz-tooltip {
