}

/* ---------- charts ---------- */
.trend {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.trend__plot {
  flex: 1;
  min-height: 0;
  margin-top: 4px;
}
.trend__plot svg {
  display: block;
  border-radius: 4px;
}
.trend__plot svg:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}
.trend svg text {
  font-family: inherit;
}
.trend .grid {
  stroke: var(--grid);
  stroke-width: 1;
}
.trend .axis {
  stroke: var(--axis);
  stroke-width: 1;
}
.trend .tick {
  fill: var(--text-muted);
  font-size: 11px;
}
.trend .line {
  fill: none;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.trend .line_cur {
  stroke: var(--series-1);
}
.trend .line_prev {
  stroke: var(--text-muted);
}
.trend .area {
  fill: var(--series-1);
  opacity: 0.1;
}
.trend .dot {
  stroke: var(--surface-1);
  stroke-width: 4; /* 2px ring outside the fill */
  paint-order: stroke;
}
.trend .dot_cur {
  fill: var(--series-1);
}
.trend .dot_prev {
  fill: var(--text-muted);
}
.trend .crosshair {
  stroke: var(--axis);
  stroke-width: 1;
}
.trend .end-label {
  fill: var(--text-primary);
  font-size: 12px;
  font-weight: 600;
}

.legend {
  display: flex;
  align-items: center;
  gap: 4px 16px;
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: 12px;
  color: var(--text-secondary);
}
.legend_wrap {
  flex-wrap: wrap;
}
.legend li {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.key {
  flex: none;
  display: inline-block;
}
.key_line {
  width: 14px;
  height: 2px;
  border-radius: 1px;
}
.key_box {
  width: 10px;
  height: 10px;
  border-radius: 2px;
}
.key_cur {
  background: var(--series-1);
}
.key_prev {
  background: var(--text-muted);
}

.hbars {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  justify-content: space-around;
  overflow: auto;
}
.hbar {
  flex: 1 1 0;
  min-height: 24px;
  max-height: 36px;
  display: grid;
  grid-template-columns: minmax(64px, 112px) 1fr;
  align-items: center;
  gap: 8px;
  padding: 0 4px;
  border-radius: 6px;
  font-size: 13px;
  outline: none;
}
.hbar_active {
  background: color-mix(in srgb, var(--text-primary) 5%, transparent);
}
.hbar:focus-visible {
  box-shadow: 0 0 0 2px var(--focus);
}
.hbar__name {
  color: var(--text-secondary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.hbar__track {
  display: flex;
  align-items: center;
  min-width: 0;
}
.hbar__bar {
  flex: none;
  height: 18px;
  min-width: 2px;
  border-radius: 0 4px 4px 0; /* square on the baseline, 4px at the data end */
  background: var(--series-1);
  transition: filter 0.15s;
}
.hbar_active .hbar__bar {
  filter: brightness(1.12);
}
.hbar__value {
  margin-left: 8px;
  font-weight: 600;
  white-space: nowrap;
}

.traffic {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 12px;
  flex: 1;
  min-height: 0;
}
.segbar {
  display: flex;
  gap: 2px; /* surface gap between blocks */
  height: 28px;
}
.seg {
  min-width: 0;
  display: flex;
  align-items: center;
  padding-left: 8px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 600;
  color: #fff;
  white-space: nowrap;
  outline: none;
  transition: filter 0.15s;
}
.seg_active {
  filter: brightness(1.1);
}
.seg:focus-visible {
  box-shadow: 0 0 0 2px var(--surface-1), 0 0 0 4px var(--focus);
}
.seg_1 { background: var(--series-1); }
.seg_2 { background: var(--series-2); }
.seg_3 { background: var(--series-3); }
.seg_4 { background: var(--series-4); color: #0b0b0b; }
.seg_5 { background: var(--series-5); }

/* ---------- tables ---------- */
.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}
.data-table th,
.data-table td {
  padding: 8px;
  text-align: left;
  white-space: nowrap;
  border-bottom: 1px solid var(--grid);
}
.data-table thead th {
  position: sticky;
  top: 0;
  z-index: 1;
  background: var(--surface-1);
  font-size: 12px;
  font-weight: 500;
  color: var(--text-secondary);
}
.data-table tbody th {
  max-width: 220px;
  overflow: hidden;
  text-overflow: ellipsis;
  font-weight: 400;
}
.data-table .num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.data-table tbody tr:last-child > * {
  border-bottom: 0;
}
.status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.status__icon {
  display: inline-flex;
}
.status__icon_good { color: var(--status-good); }
.status__icon_warning { color: var(--status-warning); }
.status__icon_critical { color: var(--status-critical); }

/* ---------- tooltip ---------- */
.viz-tooltip {
  position: fixed;
  z-index: 1000;
  min-width: 140px;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--surface-1);
  color: var(--text-primary);
  box-shadow: 0 6px 20px rgba(11, 11, 11, 0.16);
  font-size: 12px;
  line-height: 16px;
  pointer-events: none;
}
.viz-tooltip__head {
  margin-bottom: 4px;
  color: var(--text-secondary);
}
.viz-tooltip__row {
  display: flex;
  align-items: center;
  gap: 8px;
}
.viz-tooltip__row strong {
  font-size: 13px;
  font-weight: 600;
}
.viz-tooltip__row span:last-child {
  color: var(--text-secondary);
}

@media (prefers-reduced-motion: reduce) {
  .dash-grid,
  .dash-item,
  .dash-placeholder,
  .dash__content,
  .hbar__bar,
  .seg {
    transition: none;
  }
}

args.command:
(npx vite --port 5199 --host 127.0.0.1 > /tmp/vite.log 2>&1 &) ; sleep 3; cat /tmp/vite.log | tail -5
cat > /tmp/pw/shot.mjs <<'EOF'
import { chromium } from 'playwright';
const b = await chromium.launch();
const p = await b.newPage({ viewport: { width: 1280, height: 900 } });
const errs = [];
p.on('console', m => { if (['error','warning'].includes(m.type())) errs.push(m.type()+': '+m.text()); });
p.on('pageerror', e => errs.push('pageerror: '+e.message));
await p.goto('http://127.0.0.1:5199/');
await p.waitForSelector('.widget');
await p.waitForTimeout(500);
await p.screenshot({ path: '/tmp/pw/1-default.png', fullPage: true });
// hover trend chart
const svg = await p.locator('.trend__plot svg').boundingBox();
await p.mouse.move(svg.x + svg.width*0.6, svg.y + svg.height*0.5);
await p.waitForTimeout(200);
await p.screenshot({ path: '/tmp/pw/2-hover.png' });
// edit mode
await p.getByRole('button', { name: 'Настроить' }).click();
await p.waitForTimeout(300);
await p.screenshot({ path: '/tmp/pw/3-edit.png', fullPage: true });
// drag "plan" widget onto the channels position
const h = p.locator('.dash-handle').nth(5); // plan
const hb = await h.boundingBox();
await p.mouse.move(hb.x+hb.width/2, hb.y+hb.height/2);
await p.mouse.down();
await p.mouse.move(hb.x+hb.width/2-300, hb.y+hb.height/2+300, { steps: 10 });
await p.screenshot({ path: '/tmp/pw/4-dragging.png', fullPage: true });
await p.mouse.up();
await p.waitForTimeout(400);
await p.screenshot({ path: '/tmp/pw/5-dropped.png', fullPage: true });
console.log(JSON.stringify(await p.evaluate(() => localStorage.getItem('dashboard:v1')).then(s=>JSON.parse(s).layout.map(i=>[i.id,i.x,i.y,i.w,i.h].join(':')))));
console.log(errs.join('\n') || 'no console errors');
await b.close();
EOF
cd /tmp/pw && node shot.mjs

