export LD_LIBRARY_PATH=/tmp/syslibs/usr/lib/aarch64-linux-gnu:/tmp/syslibs/lib/aarch64-linux-gnu FONTCONFIG_FILE=/tmp/fonts.conf; cd /tmp/pw && cat > s2.mjs <<'EOF'
import { chromium } from 'playwright';
const b = await chromium.launch({ args: ['--no-sandbox','--disable-gpu','--no-zygote'] });
const ctx = await b.newContext({ viewport: { width: 1280, height: 900 } });
const p = await ctx.newPage();
const errs = [];
p.on('console', m => { if (['error','warning'].includes(m.type())) errs.push(m.text().slice(0,200)); });
p.on('pageerror', e => errs.push('pageerror: '+e.message));
await p.route(/fonts\.css/, r => r.fulfill(r.request().resourceType() === 'script' ? { contentType: 'text/javascript', body: 'export default ""' } : { contentType: 'text/css', body: '' }));
await p.goto('http://127.0.0.1:5199/');
await p.waitForSelector('.widget');
const layout = async () => (await p.evaluate(() => JSON.parse(localStorage.getItem('dashboard:v1')).layout)).map(i => `${i.id}:${i.x},${i.y},${i.w}x${i.h}`).join(' ');
const log = (...a) => console.log(...a);

// 1. y-axis labels + table-view toggle
await p.screenshot({ path: '/tmp/pw/a-default.png', fullPage: true });
await p.getByRole('button', { name: 'Показать таблицей' }).first().click();
log('table view rows:', await p.locator('.widget >> table tbody tr').count());
await p.getByRole('button', { name: 'Показать графиком' }).first().click();

// 2. range change dims then refreshes
const before = await p.locator('.stat__value').first().textContent();
await p.locator('.g-select').click();
await p.getByText('Последние 7 дней').click();
await p.waitForTimeout(100);
log('loading class during refetch:', await p.locator('.dash__content_loading').count());
await p.waitForTimeout(700);
log('KPI before/after range:', before, '->', await p.locator('.stat__value').first().textContent());
await p.screenshot({ path: '/tmp/pw/b-7days.png' });
await p.locator('.g-select').click(); await p.getByText('Последние 30 дней').click(); await p.waitForTimeout(700);

// 3. edit: resize "trend" by dragging corner
await p.getByRole('button', { name: 'Настроить' }).click();
const tr = p.locator('.dash-item').nth(4);
const rz = await tr.locator('.dash-resize').boundingBox();
await p.mouse.move(rz.x+14, rz.y+14); await p.mouse.down();
await p.mouse.move(rz.x+14-200, rz.y+14+160, { steps: 8 });
await p.screenshot({ path: '/tmp/pw/c-resizing.png', fullPage: true });
await p.mouse.up(); await p.waitForTimeout(300);
log('after resize:', await layout());

// 4. keyboard move + shift-resize on revenue handle
const hdl = p.locator('.dash-handle').first();
await hdl.focus();
await p.keyboard.press('ArrowRight'); await p.keyboard.press('ArrowDown');
log('after keyboard move:', (await layout()).split(' ')[0]);
await p.keyboard.press('Shift+ArrowRight');
log('after keyboard resize:', (await layout()).split(' ')[0]);
log('live region:', await p.locator('.dash-sr').textContent());

// 5. remove + add back
await p.getByRole('button', { name: /Убрать виджет «Конверсия»/ }).click();
log('widgets after remove:', await p.locator('.dash-item').count());
await p.getByRole('button', { name: 'Добавить виджет' }).click();
await p.getByRole('menuitem', { name: 'Конверсия' }).click();
log('widgets after add:', await p.locator('.dash-item').count(), '|', (await layout()).split(' ').find(s => s.startsWith('conversion')));

// 6. free mode (no gravity) leaves gaps
await p.getByText('Прижимать вверх').click();
const h2 = p.locator('.dash-handle').nth(2); const bb = await h2.boundingBox();
await p.mouse.move(bb.x+bb.width/2, bb.y+bb.height/2); await p.mouse.down();
await p.mouse.move(bb.x+bb.width/2, bb.y+bb.height/2+500, { steps: 10 }); await p.mouse.up();
await p.waitForTimeout(300);
log('free mode:', (await layout()).split(' ').find(s => s.startsWith('users') || s.startsWith('conversion')));
await p.screenshot({ path: '/tmp/pw/d-free.png', fullPage: true });

// 7. reload persistence
await p.reload(); await p.waitForSelector('.widget');
log('persisted after reload:', await layout() === await layout());
await p.getByRole('button', { name: 'Настроить' }).click();
await p.getByRole('button', { name: 'Сбросить' }).click();
log('reset:', (await layout()).split(' ').slice(0,2).join(' '));
await p.getByRole('button', { name: 'Готово' }).click();

// 8. dark theme
await p.evaluate(() => { document.body.classList.remove('g-root_theme_light'); document.body.classList.add('g-root_theme_dark'); });
await p.waitForTimeout(300);
const trend = await p.locator('.trend__plot svg').boundingBox();
await p.mouse.move(trend.x + trend.width*0.4, trend.y + trend.height*0.5);
await p.screenshot({ path: '/tmp/pw/e-dark.png', fullPage: true });
await p.evaluate(() => { document.body.classList.remove('g-root_theme_dark'); document.body.classList.add('g-root_theme_light'); });

// 9. narrow
await p.setViewportSize({ width: 420, height: 900 });
await p.waitForTimeout(400);
log('edit disabled when narrow:', await p.getByRole('button', { name: 'Настроить' }).isDisabled());
await p.screenshot({ path: '/tmp/pw/f-narrow.png', fullPage: true });
log(errs.join('\n') || 'no console errors');
await b.close();
EOF
